update public.combat_cosmetic_catalog set price_coins=greatest(1200,least(50000,price_coins*3)) where active;
update public.combat_weapon_skill_catalog sk set unlock_xp=v.xp from (values (1,2500),(2,5000),(3,8000),(4,12000),(5,16000),(6,22000),(7,30000),(8,38000),(9,48000),(10,60000)) as v(slot_number,xp) where sk.slot_number=v.slot_number;